\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Dark Developer Theme ──
\definecolor{darkbg}{HTML}{0F172A}        % deep slate/navy
\definecolor{cardbg}{HTML}{1E293B}         % slightly lighter card bg
\definecolor{primary}{HTML}{3B82F6}       % electric blue
\definecolor{secondary}{HTML}{64748B}      % muted slate
\definecolor{accent}{HTML}{22D3EE}         % cyan accent
\definecolor{gain}{HTML}{22C55E}         % bright green for gains
\definecolor{loss}{HTML}{EF4444}          % warm red for losses
\definecolor{statgreen}{HTML}{166534}     % dark green for stat bg
\definecolor{statred}{HTML}{991B1B}       % dark red for stat bg
\definecolor{white}{HTML}{F8FAFC}
\definecolor{lightgray}{HTML}{94A3B8}
\definecolor{tablerow}{HTML}{1E3A5F}

\pagecolor{darkbg}
\color{white}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{gain}$\blacktriangle$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{lightgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.3},
  },
  gaincard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{gain},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{gain},
    coltitle=gain, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={gain!50},
    valign=top, drop shadow={opacity=0.3},
  },
  losscard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{loss},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{loss},
    coltitle=loss, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={loss!50},
    valign=top, drop shadow={opacity=0.3},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{lightgray},
    coltitle=lightgray, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.3},
  },
  tablecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=12pt, right=12pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.3},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=darkbg, colframe=darkbg, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries\color{white} PYPL Programming Language}\\[6pt]
  {\fontsize{72}{86}\selectfont\bfseries\color{primary} Popularity Index}\\[10pt]
  {\fontsize{32}{40}\selectfont\color{lightgray} April 2026 — Google Trends Tutorial Search Data}\\[6pt]
  {\fontsize{26}{32}\selectfont\color{secondary} Pierre Carbonnelle, CC BY 3.0}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=darkbg, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{primary!40},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \colorbox{statgreen!40}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{gain} 36.21\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{white} Python}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{lightgray} \#1 Worldwide, +5.7\% YoY}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \colorbox{darkbg}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{primary} 13.21\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{white} C/C++}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{lightgray} \#2, +6.2\% YoY (Largest Gain)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \colorbox{statred!40}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{loss} 10.01\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{white} Java}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{lightgray} \#3, -5.4\% YoY (Largest Drop)}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ TOP 10 RANKINGS TABLE (Centerpiece) ══
\posterbox[
  tablecard, title={Top 10 Languages by Search Share}
]{name=rankings, column=1, span=3, between=row6 and row14}{
  \fontsize{28}{36}\selectfont
  \rowcolors{1}{tablerow}{darkbg}
  \begin{tabular}{|p{60mm}|p{80mm}|p{60mm}|p{60mm}|}
    \hline
    \rowcolor{darkbg}
    \multicolumn{1}{|c}{\fontsize{28}{34}\selectfont\color{accent}\bfseries Rank} &
    \multicolumn{1}{c}{\fontsize{28}{34}\selectfont\color{accent}\bfseries Language} &
    \multicolumn{1}{c}{\fontsize{28}{34}\selectfont\color{accent}\bfseries Share} &
    \multicolumn{1}{c}{\fontsize{28}{34}\selectfont\color{accent}\bfseries 1-Year Trend} \\\hline
    \rowcolor{tablerow}
    \fontsize{28}{36}\selectfont\color{white}\bfseries 1 &
    \fontsize{28}{36}\selectfont\color{gain}\bfseries Python &
    \fontsize{28}{36}\selectfont\color{white} 36.21\% &
    \fontsize{28}{36}\selectfont\color{gain} $\blacktriangle$ +5.7\% \\\hline
    \rowcolor{darkbg}
    \fontsize{28}{36}\selectfont\color{white}\bfseries 2 &
    \fontsize{28}{36}\selectfont\color{primary}\bfseries C/C++ &
    \fontsize{28}{36}\selectfont\color{white} 13.21\% &
    \fontsize{28}{36}\selectfont\color{gain} $\blacktriangle$ +6.2\% \\\hline
    \rowcolor{tablerow}
    \fontsize{28}{36}\selectfont\color{white}\bfseries 3 &
    \fontsize{28}{36}\selectfont\color{loss}\bfseries Java &
    \fontsize{28}{36}\selectfont\color{white} 10.01\% &
    \fontsize{28}{36}\selectfont\color{loss} $\blacktriangledown$ -5.4\% \\\hline
    \rowcolor{darkbg}
    \fontsize{28}{36}\selectfont\color{white}\bfseries 4 &
    \fontsize{28}{36}\selectfont\color{white} R &
    \fontsize{28}{36}\selectfont\color{white} 6.17\% &
    \fontsize{28}{36}\selectfont\color{gain} $\blacktriangle$ +1.6\% \\\hline
    \rowcolor{tablerow}
    \fontsize{28}{36}\selectfont\color{white}\bfseries 5 &
    \fontsize{28}{36}\selectfont\color{white} JavaScript &
    \fontsize{28}{36}\selectfont\color{white} 5.07\% &
    \fontsize{28}{36}\selectfont\color{loss} $\blacktriangledown$ -3.0\% \\\hline
    \rowcolor{darkbg}
    \fontsize{28}{36}\selectfont\color{white}\bfseries 6 &
    \fontsize{28}{36}\selectfont\color{white} Swift &
    \fontsize{28}{36}\selectfont\color{white} 3.15\% &
    \fontsize{28}{36}\selectfont\color{gain} $\blacktriangle$ +0.8\% \\\hline
    \rowcolor{tablerow}
    \fontsize{28}{36}\selectfont\color{white}\bfseries 7 &
    \fontsize{28}{36}\selectfont\color{white} C\# &
    \fontsize{28}{36}\selectfont\color{white} 3.00\% &
    \fontsize{28}{36}\selectfont\color{loss} $\blacktriangledown$ -3.0\% \\\hline
    \rowcolor{darkbg}
    \fontsize{28}{36}\selectfont\color{white}\bfseries 8 &
    \fontsize{28}{36}\selectfont\color{white} Rust &
    \fontsize{28}{36}\selectfont\color{white} 2.98\% &
    \fontsize{28}{36}\selectfont\color{secondary} $\rightarrow$ -0.1\% \\\hline
    \rowcolor{tablerow}
    \fontsize{28}{36}\selectfont\color{white}\bfseries 9 &
    \fontsize{28}{36}\selectfont\color{white} PHP &
    \fontsize{28}{36}\selectfont\color{white} 2.96\% &
    \fontsize{28}{36}\selectfont\color{loss} $\blacktriangledown$ -0.7\% \\\hline
    \rowcolor{darkbg}
    \fontsize{28}{36}\selectfont\color{white}\bfseries 10 &
    \fontsize{28}{36}\selectfont\color{white} Objective-C &
    \fontsize{28}{36}\selectfont\color{white} 2.57\% &
    \fontsize{28}{36}\selectfont\color{secondary} $\rightarrow$ +0.1\% \\\hline
  \end{tabular}
}

% ══ GAINERS & LOSERS ══
\posterbox[
  gaincard, title={Biggest Gainers}
]{name=gainers, column=1, between=row14 and row17}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \color{gain}\bfseries C/C++ \color{white}+6.2\% YoY — Breakout star of 2026
    \item \color{gain}\bfseries Python \color{white}+5.7\% YoY — Unchallenged leader
    \item \color{gain}\bfseries R \color{white}+1.6\% YoY — Data science demand
  \end{itemize}
}

\posterbox[
  losscard, title={Biggest Losers}
]{name=losers, column=2, between=row14 and row17}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \color{loss}\bfseries Java \color{white}-5.4\% YoY — Steepest decline
    \item \color{loss}\bfseries JavaScript \color{white}-3.0\% YoY — Under pressure
    \item \color{loss}\bfseries C\# \color{white}-3.0\% YoY — Also declining
  \end{itemize}
}

\posterbox[
  bluecard, title={5-Year Trend Spotlight}
]{name=trends, column=3, between=row14 and row17}{
  \fontsize{28}{36}\selectfont
  \colorbox{gain!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{32}\selectfont\color{gain}\bfseries Top Gainer:\color{white} C/C++ +7.0\% (5yr)
  }}\\[8pt]
  \colorbox{loss!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{32}\selectfont\color{loss}\bfseries Top Loser:\color{white} Java -7.0\% (5yr)
  }}\\[8pt]
  \vspace{4pt}
  {\fontsize{24}{30}\selectfont\color{lightgray} Python solidified \#1 position over 5 years}
}

% ══ EMERGING LANGUAGES ══
\posterbox[
  darkcard, title={Languages to Watch}
]{name=emerging, column=1, span=2, between=row17 and row20}{
  \fontsize{26}{34}\selectfont
  \begin{tabular}{|p{50mm}|p{50mm}|p{80mm}|}
    \hline
    \rowcolor{darkbg}
    \fontsize{24}{30}\selectfont\color{accent}\bfseries Language &
    \fontsize{24}{30}\selectfont\color{accent}\bfseries Share &
    \fontsize{24}{30}\selectfont\color{accent}\bfseries Trend \\\hline
    \rowcolor{tablerow}
    \fontsize{24}{30}\selectfont\color{white} Ada &
    \fontsize{24}{30}\selectfont\color{white} 2.51\% &
    \fontsize{24}{30}\selectfont\color{gain} $\blacktriangle$ +1.1\% \\\hline
    \rowcolor{darkbg}
    \fontsize{24}{30}\selectfont\color{white} Julia &
    \fontsize{24}{30}\selectfont\color{white} 0.73\% &
    \fontsize{24}{30}\selectfont\color{gain} $\blacktriangle$ +0.4\% \\\hline
    \rowcolor{tablerow}
    \fontsize{24}{30}\selectfont\color{white} Go &
    \fontsize{24}{30}\selectfont\color{white} 0.71\% &
    \fontsize{24}{30}\selectfont\color{loss} $\blacktriangledown$ -1.3\% \\\hline
    \rowcolor{darkbg}
    \fontsize{24}{30}\selectfont\color{white} Kotlin &
    \fontsize{24}{30}\selectfont\color{white} 0.90\% &
    \fontsize{24}{30}\selectfont\color{loss} $\blacktriangledown$ -0.9\% \\
    \hline
  \end{tabular}
  \vspace{4pt}
  {\fontsize{22}{28}\selectfont\color{secondary} Ada: safety-critical domains | Julia: scientific computing | Go: cloud-native decline}
}

% ══ METHODOLOGY ══
\posterbox[
  darkcard, title={How PYPL Works}
]{name=methodology, column=3, between=row17 and row20}{
  \fontsize{24}{30}\selectfont
  \colorbox{primary!20}{\parbox{0.92\linewidth}{%
    \color{white}Tracks \color{primary}\bfseries Google tutorial searches\color{white} — a leading indicator of adoption
  }}\\[6pt]
  {\fontsize{22}{28}\selectfont\color{lightgray}
  \begin{itemize}[itemsep=4pt]
    \item Sourced from Google Trends
    \item 6-month smoothing window
    \item 30 languages tracked worldwide
  \end{itemize}
  }
}

\end{tcbposter}
\end{document}

